                submitTask.addEventListener('click', () => {
                    this.startResearch();
                    modalOverlay.classList.remove('visible');
                });

                cancelTask.addEventListener('click', () => {
                    modalOverlay.classList.remove('visible');
                });

                modalOverlay.addEventListener('click', (e) => {
                    if (e.target === modalOverlay) {
                        modalOverlay.classList.remove('visible');
                    }
                });

                document.addEventListener('click', (e) => {
                    const menu = document.getElementById('action-popup-menu');
                    if (!addButton.contains(e.target) && !menu.contains(e.target)) {
                        menu.classList.remove('visible');
                    }
                });
            }

            updateUI() {
                const input = document.getElementById('message-input');
                const sendButton = document.getElementById('send-button');
                const addButton = document.getElementById('add-button');

                if (this.currentMode === 'research' || this.isResearchActive()) {
                    input.placeholder = 'Kutatási paraméterek finomítása...';
                    sendButton.className = 'mode-research';
                    addButton.style.display = 'none';
                } else {
                    input.placeholder = 'Írj üzenetet...';
                    sendButton.className = 'mode-chat';
                    addButton.style.display = 'flex';
                }
            }

            async sendMessage() {
                const input = document.getElementById('message-input');
                const message = input.value.trim();
                if (!message) return;

                this.addMessage('user', message);
                input.value = '';

                const typingIndicator = this.addTypingIndicator();

                try {
                    const response = await fetch('/chat', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ message })
                    });

                    if (!response.ok) {
                        throw new Error('Hiba a válasz során');
                    }

                    const data = await response.json();
                    typingIndicator.remove();

                    if (data.tool_calls && data.tool_calls.length > 0) {
                        for (const tool of data.tool_calls) {
                            if (tool.function.name === 'research') {
                                this.handleResearchTool(tool);
                            } else if (tool.function.name === 'search') {
                                this.handleSearchTool(tool);
                            } else if (tool.function.name === 'find_similar') {
                                this.handleFindSimilarTool(tool);
                            } else if (tool.function.name === 'contents') {
                                this.handleContentsTool(tool);
                            } else if (tool.function.name === 'answer') {
                                this.handleAnswerTool(tool);
                            } else if (tool.function.name === 'webset') {
                                this.handleWebsetTool(tool);
                            }
                        }
                    }

                    if (data.message) {
                        this.addMessage('ai', data.message);
                    }

                    if (data.research_initiated) {
                        this.showResearchView(data.research_id, message);
                    }
                } catch (error) {
                    typingIndicator.remove();
                    this.addMessage('ai', 'Sajnálom, hiba történt. Kérlek, próbáld újra.', 'error');
                    console.error(error);
                }

                this.saveChatHistory();
            }

            addMessage(sender, text, className = '') {
                const history = document.getElementById('chat-history');
                const messageDiv = document.createElement('div');
                messageDiv.className = `message ${sender} ${className}`;
                messageDiv.textContent = text;
                history.appendChild(messageDiv);
                history.scrollTop = history.scrollHeight;
            }

            addTypingIndicator() {
                const history = document.getElementById('chat-history');
                const indicator = document.createElement('div');
                indicator.className = 'message ai typing-indicator';
                indicator.innerHTML = '<span class="typing-dot"></span><span class="typing-dot"></span><span class="typing-dot"></span>';
                history.appendChild(indicator);
                history.scrollTop = history.scrollHeight;
                return indicator;
            }

            addWidget(type, goal, params, status, progress) {
                const history = document.getElementById('chat-history');
                const widget = document.createElement('div');
                widget.className = 'message widget';
                widget.innerHTML = `
                    <div class="widget-header">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                            <polyline points="22,4 12,14.01 9,11.01"></polyline>
                        </svg>
                        <h3>EXA ${type.toUpperCase()}</h3>
                    </div>
                    <div class="widget-body">
                        <div class="task-goal">${goal}</div>
                        <div class="task-params-summary">${JSON.stringify(params)}</div>
                        <div class="widget-status">${status}</div>
                        <div class="widget-progress-bar">
                            <div class="widget-progress-inner" style="width: ${progress}%"></div>
                        </div>
                    </div>
                `;
                history.appendChild(widget);
                history.scrollTop = history.scrollHeight;
            }

            showResearchModal(goal = '') {
                document.getElementById('research-goal-summary').textContent = goal || 'Mit szeretnél kutatni?';
                document.getElementById('research-options-modal-overlay').classList.add('visible');
                document.getElementById('advanced-options-container').style.display = 'none';
                document.getElementById('toggle-advanced-options').textContent = 'Speciális beállítások';
            }

            async startResearch() {
                const goal = document.getElementById('message-input').value.trim() || document.getElementById('research-goal-summary').textContent;
                const model = document.getElementById('exa-model').value;
                const numResults = parseInt(document.getElementById('num-results').value) || 100;
                const searchType = document.getElementById('search-type').value;
                const category = document.getElementById('category').value;
                const startDate = document.getElementById('start-date').value;
                const endDate = document.getElementById('end-date').value;
                const includeDomains = document.getElementById('include-domains').value.split(',').map(d => d.trim()).filter(Boolean);
                const excludeDomains = document.getElementById('exclude-domains').value.split(',').map(d => d.trim()).filter(Boolean);
                const outputSchema = document.getElementById('output-schema').value ? JSON.parse(document.getElementById('output-schema').value) : null;
                const useWebset = document.getElementById('use-webset').checked;
                const useAnswer = document.getElementById('use-answer').checked;
                const websetName = document.getElementById('webset-name').value || `Kutatás: ${goal}`;

                this.addWidget('research', goal, { model, numResults, searchType, category, startDate, endDate, includeDomains, excludeDomains, outputSchema, useWebset, useAnswer }, 'Folyamatban', 0);

                try {
                    const response = await fetch('/research', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            goal,
                            model,
                            num_results: numResults,
                            search_type: searchType,
                            category,
                            start_date: startDate,
                            end_date: endDate,
                            include_domains: includeDomains,
                            exclude_domains: excludeDomains,
                            output_schema: outputSchema,
                            use_webset: useWebset,
                            use_answer: useAnswer,
                            webset_name: websetName
                        })
                    });

                    const data = await response.json();
                    this.researchId = data.research_id;
                    this.showResearchView(this.researchId, goal);
                    this.pollResearch();
                } catch (error) {
                    this.addMessage('ai', 'Hiba a kutatás indításakor.', 'error');
                }
            }

            handleResearchTool(tool) {
                const args = tool.function.arguments;
                this.showResearchModal(args.goal);
            }

            async handleSearchTool(tool) {
                const args = tool.function.arguments;
                this.addWidget('search', args.query, { ...args, num_results: args.num_results || 100 }, 'Folyamatban', 50);

                try {
                    const response = await fetch('/exa/search', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(args)
                    });
                    const data = await response.json();
                    this.addMessage('ai', `Keresési eredmények: ${data.results.length} találat.\n${JSON.stringify(data.results.slice(0, 5), null, 2)}`);
                } catch (error) {
                    this.addMessage('ai', 'Hiba a keresés során.', 'error');
                }
            }

            async handleFindSimilarTool(tool) {
                const args = tool.function.arguments;
                this.addWidget('find_similar', args.url, args, 'Folyamatban', 50);

                try {
                    const response = await fetch('/exa/find_similar', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(args)
                    });
                    const data = await response.json();
                    this.addMessage('ai', `Hasonló linkek: ${data.results.length} találat.\n${JSON.stringify(data.results.slice(0, 5), null, 2)}`);
                } catch (error) {
                    this.addMessage('ai', 'Hiba a hasonló keresés során.', 'error');
                }
            }

            async handleContentsTool(tool) {
                const args = tool.function.arguments;
                this.addWidget('contents', `Tartalom: ${args.urls.join(', ')}`, args, 'Folyamatban', 50);

                try {
                    const response = await fetch('/exa/contents', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(args)
                    });
                    const data = await response.json();
                    this.addMessage('ai', `Tartalmak: ${data.results.length} oldal.\n${JSON.stringify(data.results.slice(0, 3), null, 2)}`);
                } catch (error) {
                    this.addMessage('ai', 'Hiba a tartalom lekérésében.', 'error');
                }
            }

            async handleAnswerTool(tool) {
                const args = tool.function.arguments;
                this.addWidget('answer', args.query, args, 'Folyamatban', 50);

                try {
                    const response = await fetch('/exa/answer', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(args)
                    });
                    const data = await response.json();
                    this.addMessage('ai', `Válasz: ${data.answer}\nForrások: ${data.citations.map(c => c.url).join(', ')}`);
                } catch (error) {
                    this.addMessage('ai', 'Hiba a válasz generálásában.', 'error');
                }
            }

            async handleWebsetTool(tool) {
                const args = tool.function.arguments;
                this.addWidget('webset', args.name, args, 'Folyamatban', 0);

                try {
                    const response = await fetch('/exa/webset', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(args)
                    });
                    const data = await response.json();
                    this.addMessage('ai', `Webset létrehozva: ${data.id}\nÁllapot: ${data.status}\nElemek: ${data.items?.length || 0}`);
                } catch (error) {
                    this.addMessage('ai', 'Hiba a webset létrehozásában.', 'error');
                }
            }

            showResearchView(researchId, title) {
                this.researchId = researchId;
                document.getElementById('research-title').textContent = title;
                document.getElementById('research-view').classList.add('visible');
                document.getElementById('chat-view').classList.add('research-active');
                this.updateResearchView();
            }

            async updateResearchView() {
                if (!this.researchId) return;

                try {
                    const response = await fetch(`/research/${this.researchId}?events=true`);
                    const data = await response.json();

                    const content = document.getElementById('research-content');
                    content.innerHTML = '';

                    if (data.status === 'completed') {
                        const section = document.createElement('div');
                        section.className = 'research-item';
                        section.innerHTML = `
                            <div class="research-item-header">
                                <h3>${data.instructions}</h3>
                                <span class="research-status status-${data.status}">Kész</span>
                            </div>
                            <div class="research-output">${data.output.content}</div>
                        `;
                        content.appendChild(section);

                        if (data.webset_id) {
                            const websetSection = document.createElement('div');
                            websetSection.innerHTML = `
                                <h3 class="research-section-title">Webset</h3>
                                <div>ID: ${data.webset_id}</div>
                            `;
                            content.appendChild(websetSection);
                        }

                        if (data.answer) {
                            const answerSection = document.createElement('div');
                            answerSection.innerHTML = `
                                <h3 class="research-section-title">Generált Válasz</h3>
                                <div>${data.answer}</div>
                            `;
                            content.appendChild(answerSection);
                        }
                    } else if (data.status === 'running') {
                        const eventsHtml = data.events.map(event => {
                            if (event.eventType === 'plan-operation' && event.data.type === 'search') {
                                return `<div>Keresés: ${event.data.query} - ${event.data.results.length} találat</div>`;
                            } else if (event.eventType === 'task-output') {
                                return `<div>Feladat kimenet: ${event.output.content}</div>`;
                            }
                            return `<div>${event.eventType}: ${JSON.stringify(event)}</div>`;
                        }).join('');

                        const section = document.createElement('div');
                        section.className = 'research-item';
                        section.innerHTML = `
                            <div class="research-item-header">
                                <h3>${data.instructions}</h3>
                                <span class="research-status status-${data.status}">Folyamatban</span>
                            </div>
                            <div class="research-output">${eventsHtml}</div>
                        `;
                        content.appendChild(section);
                    } else {
                        const section = document.createElement('div');
                        section.innerHTML = `<div class="research-status status-${data.status}">${data.status.toUpperCase()}</div>`;
                        content.appendChild(section);
                    }
                } catch (error) {
                    console.error(error);
                }
            }

            async pollResearch() {
                if (!this.researchId) return;

                const interval = setInterval(async () => {
                    await this.updateResearchView();
                    const response = await fetch(`/research/${this.researchId}`);
                    const data = await response.json();
                    if (data.status === 'completed' || data.status === 'failed' || data.status === 'canceled') {
                        clearInterval(interval);
                        this.addMessage('ai', `Kutatás befejezve: ${data.output ? data.output.content : data.error}`);
                    }
                }, 2000);
            }

            isResearchActive() {
                return !!this.researchId;
            }

            async uploadFile() {
                const input = document.createElement('input');
                input.type = 'file';
                input.multiple = true;
                input.onchange = (e) => {
                    const files = Array.from(e.target.files);
                    files.forEach(file => {
                        const formData = new FormData();
                        formData.append('file', file);
                        fetch('/upload', {
                            method: 'POST',
                            body: formData
                        }).then(res => res.json()).then(data => {
                            this.addMessage('ai', `Fájl feltöltve: ${file.name}, feldolgozva.`);
                        });
                    });
                };
                input.click();
            }

            saveChatHistory() {
                const history = Array.from(document.querySelectorAll('.message:not(.typing-indicator)')).map(msg => ({
                    sender: msg.classList.contains('user') ? 'user' : 'ai',
                    text: msg.textContent
                }));
                localStorage.setItem('chatHistory', JSON.stringify(history.slice(-50)));
            }

            loadChatHistory() {
                const saved = localStorage.getItem('chatHistory');
                if (saved) {
                    JSON.parse(saved).forEach(msg => this.addMessage(msg.sender, msg.text));
                }
            }
        }

        new App();
    </script>
</body>
