        # Poll for completion
        result = poll_exa_research(exa, research_id)
        task.status = result['status']

        if task.status == 'completed':
            task.output = result['output']['content']
            task.cost = result.get('costDollars', {'total': 0, 'numSearches': 0, 'numPages': 0, 'reasoningTokens': 0})
            add_event(task, 'research-output', {'outputType': 'completed', 'content': task.output, 'parsed': result['output'].get('parsed'), 'costDollars': task.cost})

            # If use_webset, create webset with search
            if task.params.get('use_webset'):
                webset_params = {
                    'search': {
                        'query': task.goal,
                        'count': task.params.get('num_results', 100),
                        'type': task.params.get('search_type', 'auto'),
                        'category': task.params.get('category')
                    },
                    'name': task.params.get('webset_name', f'Research Webset: {task.goal}'),
                    'description': 'Automated webset from research'
                }
                if task.params.get('start_date'):
                    webset_params['search']['startCrawlDate'] = task.params['start_date']
                if task.params.get('end_date'):
                    webset_params['search']['endCrawlDate'] = task.params['end_date']
                if task.params.get('include_domains'):
                    webset_params['search']['includeDomains'] = task.params['include_domains']
                if task.params.get('exclude_domains'):
                    webset_params['search']['excludeDomains'] = task.params['exclude_domains']

                webset_response = exa.websets.create(params=webset_params)
                task.webset_id = webset_response.id
                add_event(task, 'webset-created', {'websetId': task.webset_id})

            # If use_answer, generate answer
            if task.params.get('use_answer'):
                answer_response = exa.answer(task.goal, text=True)
                task.answer = answer_response.answer
                add_event(task, 'answer-generated', {'answer': task.answer, 'citations': [c['url'] for c in answer_response.citations]})

        elif task.status == 'failed':
            task.output = result.get('error', 'Unknown error')
            add_event(task, 'research-output', {'outputType': 'failed', 'error': task.output})

        task.end_time = time.time()
        research_tasks[task.id] = task
        return task

    except Exception as e:
        task.status = 'failed'
        task.output = str(e)
        add_event(task, 'research-output', {'outputType': 'failed', 'error': str(e)})
        research_tasks[task.id] = task
        return task

def get_llm_response(message, history):
    prompt = """You are Tiffy, a helpful AI assistant. You have access to EXA tools for advanced research and web search.

Available tools:
- research(goal: str, model: str='exa-research-pro', num_results: int=100, ...): Start autonomous research on the goal using EXA Research API with highest settings.
- search(query: str, num_results: int=100, search_type: str='auto', category: str='', ...): Perform web search with contents.
- find_similar(url: str, num_results: int=100, ...): Find similar links to the URL.
- contents(urls: list[str], text: bool=True, highlights: dict=None, summary: dict=None, ...): Get full contents from URLs.
- answer(query: str, text: bool=True): Generate answer from search.
- webset(name: str, search: dict={query: str, count: int=100, ...}): Create a webset collection.

To use a tool, output in JSON: {"tool_calls": [{"function": {"name": "research", "arguments": {"goal": "topic"}}}]}

If research makes sense, ask the user: "Szeretnél mélyebb kutatást erről? (igen/nem)" and if yes, use the tool.

Otherwise, respond normally.

History: {history}
User: {message}

Response:""".format(history=history[-10:], message=message)

    headers = {
        'Authorization': f'Bearer {CEREBRAS_API_KEY}',
        'Content-Type': 'application/json'
    }
    data = {
        "model": "llama-3.1-8b-chat",  # Changed to faster model
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": 4096,  # Increased tokens
        "temperature": 0.7,
        "stream": False
    }

    try:
        response = requests.post(CEREBRAS_URL, headers=headers, json=data, timeout=60)
        response.raise_for_status()
        result = response.json()
        full_response = result['choices'][0]['message']['content']

        # Parse tool calls
        try:
            import re
            tool_match = re.search(r'\{.*"tool_calls".*\}', full_response, re.DOTALL)
            if tool_match:
                tool_calls = json.loads(tool_match.group())
                return {'message': full_response.replace(tool_match.group(), ''), 'tool_calls': tool_calls.get('tool_calls', [])}
        except:
            pass

        # Check for research initiation
        if "Szeretnél mélyebb kutatást" in full_response and message.lower() in ['igen', 'yes']:
            return {'research_initiated': True, 'research_id': str(uuid.uuid4()), 'message': full_response}

        return {'message': full_response}
    except Exception as e:
        return {'message': f'Hiba: {str(e)}', 'tool_calls': []}

